<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted } from 'vue'
import { useWallStore } from './stores/wall'
import type { WallItem } from './types'

const wall = useWallStore()
const layoutName = computed(() => wall.payload?.layout === 'float' ? '签名漂浮墙' : '砖墙矩阵')

function seededStyle(item: WallItem, index: number) {
  let hash = 2166136261
  for (const char of item.id) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619)
  const x = 4 + Math.abs(hash % 9)
  const y = 4 + Math.abs((hash >> 5) % 8)
  const tilt = ((hash >> 11) % 5) / 5
  return { '--float-x': `${x}px`, '--float-y': `${y}px`, '--float-delay': `${-Math.abs(hash % 12000)}ms`, '--tilt': `${tilt}deg`, '--index': index } as Record<string, string | number>
}

function dateText(value: string) {
  return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit' }).format(new Date(value)).replace('/', '.')
}

onMounted(wall.start)
onBeforeUnmount(wall.stop)
</script>

<template>
  <main class="wall-screen" :class="`layout-${wall.payload?.layout || 'brick'}`">
    <div class="paper-grid" aria-hidden="true" />
    <div class="ambient-rings" aria-hidden="true"><i /><i /><i /></div>
    <header class="wall-header">
      <div class="school-brand"><div class="school-seal"><span>淳安</span><strong>三</strong><small>中</small></div><div><p>CHUN'AN NO.3 MIDDLE SCHOOL</p><strong>{{ wall.payload?.schoolName || '淳安第三中学' }}</strong><span>校史文化展厅 · 签名展示墙</span></div></div>
      <div class="title-block"><p>LEAVE YOUR MARK</p><h1>{{ wall.payload?.title || '一笔一画，汇成三中记忆' }}</h1><span><i />每一份笔迹，都是校园记忆的一块砖</span></div>
      <div class="wall-meta"><span class="mode-mark">{{ layoutName }}</span><strong>{{ wall.payload?.items.length || 0 }}</strong><small>份签名共同上墙</small></div>
    </header>

    <section v-if="wall.loading && !wall.payload" class="wall-state"><div class="loading-seal">签</div><h2>正在铺陈签名墙</h2><p>请稍候，校园记忆正在汇聚</p></section>
    <section v-else-if="!wall.visibleItems.length" class="wall-state"><div class="loading-seal">待</div><h2>静候第一份签名</h2><p>审核通过的签名将在这里温暖呈现</p></section>
    <section v-else class="signature-stage" :class="`is-${wall.payload?.layout || 'brick'}`">
      <article v-for="(item, index) in wall.visibleItems" :key="item.id" class="signature-card" :style="seededStyle(item, index)">
        <div class="card-corners" aria-hidden="true"><i /><i /><i /><i /></div>
        <span class="brick-number">{{ String((wall.page * 24) + index + 1).padStart(3, '0') }}</span>
        <div class="signature-image"><img :src="item.imageUrl" :alt="`${item.displayName}的签名`" /></div>
        <footer><div><strong>{{ item.displayName }}</strong><span v-if="item.identity !== 'anonymous'">{{ item.identityLabel }}</span></div><time>{{ dateText(item.createdAt) }}</time></footer>
      </article>
    </section>

    <footer class="wall-footer"><div><span class="red-rule" />SIGNATURE ARCHIVE<span class="red-rule" /></div><div v-if="wall.pages > 1" class="page-dots" aria-label="展示页码"><i v-for="index in wall.pages" :key="index" :class="{ active: index - 1 === wall.page }" /></div><span class="footer-place">浙江 · 淳安 <b>·</b> 校园记忆共创</span></footer>

    <div v-if="wall.offline" class="offline-note"><i />网络暂时中断 · 正在展示最近缓存</div>

    <Transition name="spotlight">
      <div v-if="wall.spotlightVisible && wall.spotlight" class="spotlight" aria-live="polite">
        <div class="spotlight-rings" aria-hidden="true"><i /><i /></div>
        <section><p>NEW SIGNATURE · 新签名上墙</p><div class="spotlight-paper"><img :src="wall.spotlight.imageUrl" alt="最新审核通过的签名" /></div><h2>{{ wall.spotlight.displayName }}</h2><span>{{ wall.spotlight.identity === 'anonymous' ? '匿名参与' : wall.spotlight.identityLabel }} · 感谢为校园记忆添上一笔</span></section>
      </div>
    </Transition>
  </main>
</template>

